import {esc} from './ui.js';import {importClient} from './import-api.js';
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v??'待补齐')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export function mountImport(root,{onSaved,client=importClient}={}){
 let alive=true,preview=null,busy=false,generation=0;
 root.innerHTML=`<section class="panel import-intro"><h2>导入标准订单数据</h2><p>一次导入完整周期，按日期逐步查看生产进度和利润差距。</p><div class="import-steps"><span>1 选择两份 Excel</span><span>2 校验并预览</span><span>3 确认保存</span></div><div class="import-file-grid"><label class="file-card">成本 Excel<input id="cost-file" type="file" accept=".xlsx" aria-label="选择成本Excel"><small>订单信息、原订单用量、补单用量、成本计算 · A-ORDER-0.2</small></label><label class="file-card">每日 Excel<input id="daily-file" type="file" accept=".xlsx" aria-label="选择每日Excel"><small>每日生产、每日材料、每日费用 · 配套 v0.2</small></label></div><div class="import-actions"><button class="button primary" id="preview-files" disabled>解析并预览</button><span class="muted">每份最大10MiB · .xlsx</span></div><p class="footnote">文件在本机服务解析。确认后保存规范化输入及版本；每日实际利润由服务端重算。</p><div id="import-status" role="status" aria-live="polite"></div></section><div id="import-preview"></div>`;
 const cost=root.querySelector('#cost-file'),daily=root.querySelector('#daily-file'),parse=root.querySelector('#preview-files'),status=root.querySelector('#import-status'),output=root.querySelector('#import-preview');
 const changed=()=>{generation++;preview=null;output.innerHTML='';status.textContent='';parse.disabled=busy||!cost.files[0]||!daily.files[0];};cost.addEventListener('change',changed);daily.addEventListener('change',changed);
 const draw=()=>{
  const p=preview,s=p.summary,errors=p.issues.filter(x=>x.severity==='error'),missing=p.issues.filter(x=>x.severity==='missing');
  output.innerHTML=`<section class="panel import-preview"><div class="panel-head"><h2>识别结果 · ${esc(s.orderId||'订单待确认')}</h2><span class="demo-pill">${s.isDemo?'模拟数据':'导入资料'}</span></div><div class="panel-body"><div class="kv-grid"><div>核算子项<strong>${esc(s.lineId)}</strong></div><div>日期范围<strong>${esc(s.start)} — ${esc(s.end)}</strong></div><div>基线版本<strong>${esc(s.baselineId)}</strong></div><div>资料版本<strong>${esc(s.revisionId)}</strong></div></div><div class="import-counts">生产 ${s.counts.production} 条 · 补单 ${s.counts.supplements} 条 · 材料 ${s.counts.materials} 条 · 费用 ${s.counts.expenses} 条</div><div class="note ${errors.length||missing.length?'warning':''}">${errors.length?`${errors.length} 项错误需要修正`:missing.length?`${missing.length} 项资料待补齐，相关利润暂不可用`:'格式校验通过，可以确认导入'}。补单关联保留，已包含的加工量和材料不会再叠加。</div></div>${p.issues.length?table(['级别','工作表 / 单元格','字段 / 记录','说明'],p.issues.slice(0,200).map(x=>[x.severity==='error'?'错误':x.severity==='missing'?'缺失':'提示',`${x.sheet||''} ${x.cell||''}`,x.field||x.recordId||'',x.message])):''}<div class="panel-body import-actions">${missing.length?'<label><input type="checkbox" id="allow-incomplete"> 明确保存为待补齐版本</label>':''}<button class="button primary" id="commit-import" ${!p.canCommit?'disabled':''}>${missing.length?'保存待补齐版本':'确认导入'}</button><span class="muted">预览有效期10分钟</span></div></section><section class="panel import-preview"><div class="panel-head"><h2>每日生产预览</h2><span class="muted">最多展示前200条，确认后保存全部</span></div>${table(['日期','码号','加工量','不良量','记录状态','来源单元格'],p.preview.production.map(r=>[r.date,r.size,r.processed,r.defects,r.dayStatus,`${r.source.sheet}!${r.source.cell}`]))}</section><details class="panel import-preview"><summary>展开材料、费用和补单预览</summary><h3>每日材料</h3>${table(['日期','材料编号','实际净耗kg','实际单价元/kg'],p.preview.materials.map(r=>[r.date,r.materialId,r.net,r.price]))}<h3>每日费用</h3>${table(['日期','类别','项目','金额元'],p.preview.expenses.map(r=>[r.date,r.category,r.item,r.amount]))}<h3>补单关联</h3>${table(['日期','码号','数量','生产记录','计入规则'],p.preview.supplements.map(r=>[r.date,r.size,r.quantity,r.parentId,r.inclusion]))}</details>`;
  output.querySelector('#commit-import')?.addEventListener('click',async()=>{
   if(busy)return;const allow=output.querySelector('#allow-incomplete')?.checked??false;if(p.requiresIncomplete&&!allow){status.textContent='请先勾选保存为待补齐版本，或修正数据后重新解析。';return;}
   busy=true;const btn=output.querySelector('#commit-import');btn.disabled=true;status.textContent='正在保存数据版本…';
   try{const r=await client.commitPreview(p.previewId,allow,p.digest);if(alive){status.textContent=r.reused?'此版本已存在，未重复追加。':'数据版本已保存。';onSaved?.(r);}}catch(e){if(alive){status.textContent=e.message;btn.disabled=!p.canCommit;}}finally{busy=false;}
  });
 };
 parse.addEventListener('click',async()=>{
  if(busy)return;const c=cost.files[0],d=daily.files[0];if(!c||!d)return;
  if([c,d].some(f=>!f.name.toLowerCase().endsWith('.xlsx')||f.size>10*1024*1024)){status.textContent='请选择不超过10MiB的.xlsx文件。';return;}
  const gen=++generation;busy=true;parse.disabled=true;cost.disabled=true;daily.disabled=true;status.textContent='正在读取并校验两份表格…';output.innerHTML='';
  try{const r=await client.previewFiles(c,d);if(alive&&gen===generation){preview=r;draw();status.textContent='预览已生成，请核对订单与校验结果。';}}catch(e){if(alive)status.textContent=e.message;}finally{busy=false;if(alive){cost.disabled=false;daily.disabled=false;parse.disabled=!cost.files[0]||!daily.files[0];}}
 });
 return ()=>{alive=false;generation++;};
}
